object DealLoader {
    fun load(
        scope: CoroutineScope,
        loader: suspend () -> Product,
        onLoaded: (Product) -> Unit = {},
        showDeal: (String) -> Unit,
    ) {
        scope.launch {
            val product = loader()
            onLoaded(product)
            if (product.dealPercent > 0) {
                showDeal("${product.dealPercent}% off ${product.name}, today only.")
            }
        }
    }
}

@Composable
fun DetailScreen(productId: Int, onBuyNow: (Int) -> Unit, modifier: Modifier = Modifier) {
    val activity = LocalContext.current as FragmentActivity
    var product by remember { mutableStateOf<Product?>(null) }
    LaunchedEffect(productId) {
        DealLoader.load(
            scope = this,
            loader = { ProductRepository.byId(productId) },
            onLoaded = { product = it },
            showDeal = { message ->
                if (activity.lifecycle.currentState.isAtLeast(Lifecycle.State.STARTED)) {
                    DealDialogFragment.newInstance(message).show(activity.supportFragmentManager, "deal")
                }
            },
        )
    }

